from common import Q
A="aqeedah"
Q(A,1,"How many articles of faith (arkan al-iman) are there?","6",["5","4","7"],"Belief in Allah, His angels, books, messengers, the Last Day, and the decree — its good and bad.","Sahih Muslim 8")
Q(A,1,"Which of these is a pillar of Islam rather than an article of faith?","Hajj",["Belief in angels","Belief in the books","Belief in the Last Day"],"Hajj is one of the five pillars of Islam; the six articles of faith are matters of belief.","Sahih Muslim 8")
Q(A,1,"What does Tawhid mean?","Affirming the Oneness of Allah",["Belief in many gods","Love of the Prophet ﷺ","Giving charity"],"Tawhid is believing that Allah is One, without partner, in His essence, attributes and actions.","Quran 112")
Q(A,2,"What are the two great schools of Sunni creed (aqidah)?","Ash'ari and Maturidi",["Hanafi and Shafi'i","Qadiri and Chishti","Mu'tazili and Jahmi"],"The Ash'ari and Maturidi schools are the creed of Ahl as-Sunnah wal-Jama'ah; the madhhabs are schools of fiqh.","Al-Zabidi, Ithaf as-Sadah al-Muttaqin 2/6")
Q(A,2,"Imam Abu Mansur al-Maturidi was from which city?","Samarqand",["Baghdad","Cairo","Damascus"],"Imam al-Maturidi (d. 333 AH) of Samarqand systematised the creed of the Hanafi scholars.","Ta'wilat Ahl as-Sunnah")
Q(A,3,"Imam Abu al-Hasan al-Ash'ari was a descendant of which Companion?","Abu Musa al-Ash'ari",["Abu Hurayrah","Abu Dharr","Abu Ayyub al-Ansari"],"He descended from Abu Musa al-Ash'ari; the Prophet ﷺ praised the people of Abu Musa (Quran 5:54 commentary).","Ibn Asakir, Tabyin Kadhib al-Muftari")
Q(A,1,"Complete the verse: 'There is nothing…'","like unto Him",["above Him","before Him","equal in number"],"'There is nothing like unto Him, and He is the All-Hearing, the All-Seeing.'","Quran 42:11")
Q(A,2,"Allah exists without a beginning. What is this attribute called?","Al-Qidam",["Al-Baqa'","Al-Wahdaniyyah","Al-Qudrah"],"Qidam: Allah has no beginning. Baqa': He has no end.","Quran 57:3; Umm al-Barahin")
Q(A,2,"Allah exists without an end. What is this attribute called?","Al-Baqa'",["Al-Qidam","Al-Iradah","Al-Kalam"],"'Everything will perish except His Face.'","Quran 28:88; Umm al-Barahin")
Q(A,2,"'Mukhalafatuhu lil-hawadith' means that Allah…","is unlike His creation in every way",["is created","changes over time","needs a place"],"Nothing in creation resembles Allah, and He resembles nothing in creation.","Quran 42:11; al-Aqidah at-Tahawiyyah")
Q(A,2,"Who will be given the 'Praised Station' (al-Maqam al-Mahmud) of the great intercession?","Prophet Muhammad ﷺ",["Prophet Ibrahim","Prophet Isa","The angels"],"On the Day of Judgement people go to the prophets until they come to Muhammad ﷺ, who intercedes.","Quran 17:79; Sahih al-Bukhari 4712")
Q(A,1,"Who is the final prophet?","Muhammad ﷺ",["Isa","Musa","Ibrahim"],"He ﷺ is 'the Messenger of Allah and the Seal of the Prophets'.","Quran 33:40")
Q(A,2,"Prophets are protected from sin. What is this protection called?","'Ismah",["Taqwa","Barakah","Karamah"],"All prophets are protected (ma'sum) from sins, as they are the examples to be followed.","Al-Fiqh al-Akbar")
Q(A,2,"A wondrous event granted to a saint (wali) is called…","Karamah",["Mu'jizah","Sihr","Istidraj"],"Ahl as-Sunnah affirm the karamat of the awliya, as narrated about Maryam and the Companions of the Cave.","Al-Aqidah at-Tahawiyyah; Quran 3:37")
Q(A,1,"What is the greatest miracle of the Prophet ﷺ?","The Quran",["Splitting the moon","Water from his fingers","The Night Journey"],"Every prophet was given signs; 'what I have been given is the revelation'.","Sahih al-Bukhari 4981")
Q(A,2,"What do Ahl as-Sunnah believe about seeing Allah in Paradise?","The believers will see Him, without 'how' or likeness",["It is impossible","Only the angels will","Only in dreams"],"'Faces that Day will be radiant, looking at their Lord.' Ahl as-Sunnah affirm the vision without encompassing or likeness.","Quran 75:22–23; al-Aqidah at-Tahawiyyah")
Q(A,2,"Which classic creed was written by Imam Abu Ja'far at-Tahawi?","Al-Aqidah at-Tahawiyyah",["Ihya Ulum ad-Din","Al-Hikam","Umm al-Barahin"],"It records the creed of Abu Hanifa and his two companions, accepted by all Ahl as-Sunnah.","Al-Aqidah at-Tahawiyyah")
Q(A,2,"'Al-Fiqh al-Akbar', an early creed, is attributed to which imam?","Imam Abu Hanifa",["Imam Malik","Imam al-Ghazali","Imam an-Nawawi"],"It is attributed to Imam Abu Hanifa; 'the greater fiqh' means creed.","Al-Fiqh al-Akbar")
Q(A,1,"Which two angels question a person in the grave?","Munkar and Nakir",["Jibril and Mika'il","Harut and Marut","Raqib and Atid"],"The Prophet ﷺ named the two questioning angels Munkar and Nakir.","Sunan at-Tirmidhi 1071")
Q(A,2,"What is the bridge over Hell that all must cross called?","As-Sirat",["Al-Mizan","Al-A'raf","Al-Kawthar"],"The Sirat is set over Hell; believers cross according to their deeds.","Sahih al-Bukhari 806")
Q(A,1,"Which book was revealed to Prophet Musa?","The Tawrah",["The Zabur","The Injil","The Suhuf of Ibrahim"],"The Tawrah was given to Musa, the Zabur to Dawud, the Injil to Isa.","Quran 5:44; 4:163; 5:46")
Q(A,2,"What is the angel of death called in the Quran?","Malak al-Mawt",["Ridwan","Malik","Israfil"],"'The Angel of Death who has been put in charge of you will take your souls.' He is commonly called Azra'il.","Quran 32:11")
Q(A,1,"Which angel will blow the Trumpet?","Israfil",["Jibril","Mika'il","Munkar"],"Israfil will blow the Sur on the Last Day.","Quran 39:68; Sunan at-Tirmidhi 2431")
Q(A,1,"What is shirk?","Associating partners with Allah",["Missing a prayer","Lying","Being impatient"],"Allah does not forgive shirk for one who dies upon it, and forgives other than that for whom He wills.","Quran 4:48")
Q(A,1,"Belief in Qadar (the Divine Decree) means believing…","everything, good and bad, happens by Allah's decree",["humans create their own fate alone","only good is from Allah","the future is unknown to Allah"],"It is the sixth article of faith; people still choose and are accountable.","Sahih Muslim 8")
Q(A,3,"In the Maturidi school, faith (iman) in its essence is…","Conviction of the heart and affirmation by the tongue",["Only good deeds","Only speaking the Shahadah","Knowledge of Arabic"],"Deeds complete faith and are its fruit, but are not part of its essence; the Ash'aris define it as the heart's conviction, with the tongue as a condition of worldly rulings.","Al-Fiqh al-Akbar; al-Aqidah an-Nasafiyyah")
Q(A,2,"How many prophets are mentioned by name in the Quran?","25",["10","124,000","313"],"Twenty-five prophets are named; there were many more, whom Allah sent to every nation.","Quran 4:164; 6:83–86")
Q(A,1,"Who was the first prophet?","Adam",["Nuh","Ibrahim","Idris"],"Adam (peace be upon him) was the first human and the first prophet.","Musnad Ahmad 22288")
Q(A,2,"Which of these is NOT one of the Ulul 'Azm (prophets of firm resolve)?","Yunus",["Nuh","Ibrahim","Musa"],"The Ulul 'Azm are Nuh, Ibrahim, Musa, Isa and Muhammad (peace be upon them).","Quran 46:35; 33:7")
Q(A,2,"What do Muslims believe about Prophet Isa (Jesus)?","He was raised alive to Allah and will return before the Hour",["He was crucified","He was the son of God","He never existed"],"'They did not kill him, nor crucify him… rather Allah raised him to Himself.' He will descend near the end of time.","Quran 4:157–158; Sahih Muslim 155")
Q(A,2,"Who is the Dajjal?","The great false messiah who appears before the Hour",["An angel","A righteous king","A companion"],"The Prophet ﷺ taught us to seek refuge from the trial of the Dajjal in every prayer.","Sahih Muslim 588")
Q(A,2,"From which family did the Prophet ﷺ say the Mahdi will be?","His family (Ahl al-Bayt), from the descendants of Fatimah",["The Umayyads","The Abbasids","The Ansar"],"'The Mahdi is from my family, from the descendants of Fatimah.'","Sunan Abi Dawud 4284")
Q(A,2,"According to Ahl as-Sunnah, who is the best of the Companions?","Abu Bakr, then Umar, then Uthman, then Ali",["Ali, then Abu Bakr","All equal in rank","Only those of Badr"],"Ahl as-Sunnah rank the four caliphs in the order of their caliphate and love all the Companions and the Ahl al-Bayt.","Sahih al-Bukhari 3655; al-Aqidah at-Tahawiyyah")
Q(A,3,"Seeking Allah's help through the rank of the Prophet ﷺ (tawassul) is…","Permissible according to the majority of Ahl as-Sunnah",["Shirk","Only allowed for angels","Never mentioned in hadith"],"The Prophet ﷺ taught a blind man to say 'I turn to You through Your Prophet Muhammad, the Prophet of mercy'.","Sunan at-Tirmidhi 3578; Ibn Majah 1385")
Q(A,3,"Imam at-Tahawi wrote that Allah is not contained by…","the six directions",["the hearts of believers","the Quran","His attributes"],"'He is not contained by the six directions as created things are.' Allah is free of place and direction.","Al-Aqidah at-Tahawiyyah")

H="history"
Q(H,1,"Who was the first caliph after the Prophet ﷺ?","Abu Bakr as-Siddiq",["Umar","Uthman","Ali"],"The Companions pledged allegiance to Abu Bakr in 11 AH.","Sahih al-Bukhari 3668")
Q(H,1,"Who was the second caliph?","Umar ibn al-Khattab",["Abu Bakr","Uthman","Ali"],"Umar al-Faruq led from 13 to 23 AH.","Tarikh at-Tabari")
Q(H,1,"Who was the third caliph?","Uthman ibn Affan",["Ali","Umar","Mu'awiyah"],"Uthman Dhun-Nurayn led from 23 to 35 AH.","Tarikh at-Tabari")
Q(H,1,"Who was the fourth caliph?","Ali ibn Abi Talib",["Hasan","Uthman","Umar"],"Ali led from 35 to 40 AH.","Tarikh at-Tabari")
Q(H,2,"Under which caliph did the Hijri calendar begin to be used?","Umar ibn al-Khattab",["Abu Bakr","Uthman","Ali"],"Umar, with the Companions, dated the calendar from the Hijrah.","Sahih al-Bukhari 3934")
Q(H,1,"Which year of the Gregorian calendar is 1 AH?","622 CE",["570 CE","610 CE","632 CE"],"The Hijrah to Madinah took place in 622 CE.","Standard chronology")
Q(H,2,"Under which caliph did the Muslims enter Jerusalem peacefully?","Umar ibn al-Khattab",["Abu Bakr","Uthman","Harun ar-Rashid"],"Umar came in person to receive the city in about 637 CE.","Tarikh at-Tabari")
Q(H,2,"Which sultan conquered Constantinople in 1453?","Sultan Mehmed II",["Suleiman the Magnificent","Salahuddin","Alp Arslan"],"Mehmed II, 'al-Fatih', conquered Constantinople, fulfilling a hadith about its conquest.","Musnad Ahmad 18957")
Q(H,1,"Who liberated Jerusalem from the Crusaders in 1187?","Salahuddin al-Ayyubi",["Nur ad-Din Zangi","Baybars","Mehmed II"],"After the Battle of Hattin, Salahuddin entered Jerusalem and spared its people.","Ibn Shaddad, an-Nawadir as-Sultaniyyah")
Q(H,2,"Who led the Muslim army into al-Andalus (Spain) in 711?","Tariq ibn Ziyad",["Musa ibn Nusayr","Uqbah ibn Nafi","Abd ar-Rahman I"],"Gibraltar (Jabal Tariq) is named after him.","Tarikh at-Tabari")
Q(H,1,"Which dynasty ruled after the Rightly Guided Caliphs?","The Umayyads",["The Ottomans","The Abbasids","The Mughals"],"The Umayyad caliphate ruled from Damascus from 41 AH (661 CE).","Tarikh at-Tabari")
Q(H,1,"What was the capital of the Abbasid caliphate?","Baghdad",["Damascus","Cairo","Cordoba"],"Al-Mansur founded Baghdad in 762 CE.","Tarikh at-Tabari")
Q(H,2,"The 'House of Wisdom' (Bayt al-Hikmah) was in which city?","Baghdad",["Cordoba","Istanbul","Delhi"],"It was a great library and centre of translation under the Abbasids.","Ibn an-Nadim, al-Fihrist")
Q(H,2,"Which Umayyad ruler is often called the 'fifth Rightly Guided Caliph'?","Umar ibn Abd al-Aziz",["Abd al-Malik","Al-Walid","Hisham"],"His justice and piety led the scholars to count him with the Rightly Guided Caliphs.","Siyar A'lam an-Nubala")
Q(H,1,"Which Mughal emperor built the Taj Mahal?","Shah Jahan",["Akbar","Aurangzeb","Babur"],"Shah Jahan built it in Agra in memory of Mumtaz Mahal.","Standard history")
Q(H,2,"Who brought Islam to Sindh in 711–712?","Muhammad ibn Qasim",["Mahmud of Ghazni","Babur","Tariq ibn Ziyad"],"The young Umayyad commander Muhammad ibn Qasim conquered Sindh and Multan.","Chach Nama; al-Baladhuri")
Q(H,1,"Who founded the Ottoman state?","Osman I",["Mehmed II","Orhan","Suleiman"],"The Ottomans are named after Osman Ghazi.","Standard history")
Q(H,2,"In which year did the Mongols sack Baghdad?","1258",["1099","1453","1187"],"Hulagu's army destroyed Baghdad and ended the Abbasid caliphate there.","Ibn Kathir, al-Bidayah wan-Nihayah")
Q(H,2,"Al-Azhar is in which city?","Cairo",["Fez","Damascus","Baghdad"],"Founded in 970 CE, it became a great Sunni centre of learning.","Al-Maqrizi, al-Khitat")
Q(H,2,"Who founded the University of al-Qarawiyyin in Fez?","Fatimah al-Fihri",["Ibn Khaldun","Zubaydah","Mansa Musa"],"Fatimah al-Fihri founded it in 859 CE; it is among the oldest universities still operating.","Ibn Abi Zar', Rawd al-Qirtas")
Q(H,2,"The great traveller Ibn Battuta was from which city?","Tangier",["Baghdad","Delhi","Cordoba"],"He set out from Tangier in 1325 and travelled for nearly thirty years.","Ibn Battuta, ar-Rihlah")
Q(H,2,"Which scholar's name gave us the word 'algorithm'?","Al-Khwarizmi",["Ibn Sina","Al-Biruni","Al-Kindi"],"Al-Khwarizmi wrote the book from which 'algebra' also gets its name.","Standard history of science")
Q(H,2,"Who wrote 'The Canon of Medicine'?","Ibn Sina",["Ar-Razi","Ibn Rushd","Az-Zahrawi"],"Ibn Sina's al-Qanun was a standard medical text for centuries.","Al-Qanun fi at-Tibb")
Q(H,2,"Mansa Musa, famous for his Hajj with great wealth, ruled which empire?","Mali",["Songhai","Egypt","Andalus"],"Mansa Musa made his Hajj in 1324.","Al-Umari, Masalik al-Absar")
Q(H,2,"In which year was the Ottoman caliphate abolished?","1924",["1918","1857","1947"],"The Turkish Grand National Assembly abolished it on 3 March 1924.","Standard history")
Q(H,2,"Who built the Dome of the Rock?","Abd al-Malik ibn Marwan",["Salahuddin","Umar ibn al-Khattab","Suleiman"],"The Umayyad caliph Abd al-Malik completed it around 691 CE.","Its foundation inscription")
Q(H,1,"Which ruler was known as the 'Tiger of Mysore'?","Tipu Sultan",["Haidar Ali","Aurangzeb","Bahadur Shah Zafar"],"Tipu Sultan resisted the British until he was martyred in 1799.","Standard history")
Q(H,2,"Who was the field commander of the Muslims at the Battle of Yarmouk (636)?","Khalid ibn al-Walid",["Amr ibn al-As","Sa'd ibn Abi Waqqas","Al-Muthanna ibn Harithah"],"Khalid, 'the Sword of Allah', led the field command at Yarmouk.","Tarikh at-Tabari")
Q(H,2,"Who commanded the Muslims at the Battle of al-Qadisiyyah?","Sa'd ibn Abi Waqqas",["Khalid ibn al-Walid","Amr ibn al-As","Al-Muthanna"],"Sa'd led the army that defeated the Sasanian Persians.","Tarikh at-Tabari")
Q(H,3,"Which Seljuk sultan won the Battle of Manzikert in 1071?","Alp Arslan",["Tughril Beg","Malik Shah","Sanjar"],"The victory opened Anatolia to the Muslims.","Ibn al-Athir, al-Kamil")
Q(H,1,"Who founded the Mughal Empire?","Babur",["Akbar","Humayun","Shah Jahan"],"Babur won at Panipat in 1526.","Baburnama")
Q(H,2,"Which caliph was known as 'Dhun-Nurayn' (possessor of two lights)?","Uthman ibn Affan",["Ali","Umar","Abu Bakr"],"He married two daughters of the Prophet ﷺ, Ruqayyah and then Umm Kulthum.","Tarikh at-Tabari")
Q(H,3,"Which Abbasid caliph was famous in the time of Imam Abu Yusuf and the 'Thousand and One Nights' tales?","Harun ar-Rashid",["Al-Ma'mun","Al-Mansur","Al-Mu'tasim"],"Harun ar-Rashid ruled 786–809 CE; Imam Abu Yusuf was his chief judge.","Tarikh Baghdad")
